+import { addErrorDetailIf } from "../helpers/helpers.cjs";
+import { getHeadingLevel } from "../helpers/micromark-helpers.cjs";
+import { filterByTypesCached } from "./cache.mjs";
+
+/** @type {import("markdownlint").Rule} */
+export default {
+  "names": [ "MD061", "heading-max-level" ],
+  "description": "Heading level should not exceed the maximum",
+  "tags": [ "headings" ],
+  "parser": "micromark",
+  "function": function MD061(params, onError) {
+    const maximum = Number(params.config.maximum || 6);
+    for (const heading of filterByTypesCached([ "atxHeading", "setextHeading" ])) {
+      const level = getHeadingLevel(heading);
+      if (level > maximum) {
+        addErrorDetailIf(
+          onError,
+          heading.startLine,
+          `h${maximum}`,
+          `h${level}`
+        );
+      }
+    }
+  }
+};
